// Cheap sentiment fallback: scan for positive/negative cues + intensity marks.
function _sentiment(text){
  const t=(text||'').toLowerCase();
  let v=0,e=0.5,hits=0;
  const POS=/good|nice|love|happy|bright|warm|soft|light|hope|joy|dob|kras|jasn|tepl|svetl/;
  const NEG=/bad|dark|cold|hard|hurt|cry|loss|alone|zl|temn|stud|tvrd|sam|plak/;
  const HI=/storm|fire|fast|loud|burn|rush|búr|bur|rýchl|rychl|hlas|oheň|ohen/;
  const LO=/slow|soft|sleep|still|quiet|pomal|tich|spán|span/;
  if(POS.test(t)){v+=0.5;hits++;} if(NEG.test(t)){v-=0.5;hits++;}
  if(HI.test(t)){e+=0.3;hits++;} if(LO.test(t)){e-=0.3;hits++;}
  // exclamation / caps → more energy
  if(/!/.test(text||'')) e+=0.15;
  return {v:Math.max(-1,Math.min(1,v)), e:Math.max(0,Math.min(1,e)), hits};
}
// Map analysed {v,e} to concrete musical parameters.
function _moodParams(text){
  let v=0,e=0.5,matched=false;
  for(const [re,p] of _MOOD_LEX){ if(re.test(text)){ v=p.v; e=p.e; matched=true; break; } }
  if(!matched){ const s=_sentiment(text); v=s.v; e=s.e; }
  // tempo: low energy ~60, high energy ~140
  const tempo=Math.round(60+e*80);
  // scale: positive valence → major-ish, negative → minor/darker
  // intervals are semitone offsets from the tonic
  const major=[0,2,4,5,7,9,11], minor=[0,2,3,5,7,8,10];
  const harmMinor=[0,2,3,5,7,8,11], lydian=[0,2,4,6,7,9,11];
  let scale; if(v>=0.5) scale=(e>0.7?lydian:major); else if(v>=0) scale=major; else if(v>-0.6) scale=minor; else scale=harmMinor;
  // tonic: brighter moods higher, darker lower (C=0 ... pick a root pitch class)
  const root = v>=0.3 ? 0 /*C*/ : v>=-0.3 ? 7 /*G*/ : 2 /*D*/;
  // density: energetic = shorter notes, more of them
  const beatStep = e>0.8?0.5 : e>0.55?1 : e>0.3?1.5 : 2;
  return {v,e,tempo,scale,root,beatStep,matched};
}
// ── Rich offline arranger ───────────────────────────────────────────────────
// Turns a mood profile (root / mode / character / tempo) into a full multi-layer
// piece: moving bass + syncopated comping + an arced melody with 7th-chord
// colour — the same approach used for the hand-crafted library. No network.
const _RA_SCALE={major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10],dorian:[0,2,3,5,7,9,10],lydian:[0,2,4,6,7,9,11]};
const _RA_CHORD={maj:[0,4,7],min:[0,3,7],dom7:[0,4,7,10],min7:[0,3,7,10],maj7:[0,4,7,11]};
const _RA_PROG={
 'major|bright':[[0,'maj'],[7,'maj'],[9,'min7'],[5,'maj'],[2,'min7'],[7,'dom7'],[0,'maj'],[7,'dom7']],
 'major|gentle':[[0,'maj7'],[4,'min'],[5,'maj'],[0,'maj'],[2,'min7'],[7,'dom7'],[0,'maj'],[7,'maj']],
 'major|grand':[[0,'maj'],[7,'maj'],[9,'min'],[4,'min'],[5,'maj'],[0,'maj'],[5,'maj'],[7,'dom7']],
 'major|dreamy':[[0,'maj7'],[2,'min7'],[5,'maj7'],[7,'maj'],[9,'min7'],[5,'maj7'],[2,'min7'],[7,'dom7']],
 'major|driving':[[0,'maj'],[7,'maj'],[5,'maj'],[7,'maj'],[9,'min7'],[5,'maj'],[7,'dom7'],[0,'maj']],
 'minor|sad':[[0,'min'],[8,'maj'],[5,'min'],[7,'dom7'],[0,'min'],[5,'min'],[7,'dom7'],[0,'min']],
 'minor|aggressive':[[0,'min'],[0,'min'],[8,'maj'],[10,'maj'],[0,'min'],[8,'maj'],[7,'dom7'],[0,'min']],
 'minor|driving':[[0,'min'],[5,'min'],[8,'maj'],[10,'maj'],[0,'min'],[5,'min'],[7,'dom7'],[0,'min']],
 'minor|grand':[[0,'min'],[8,'maj'],[3,'maj'],[10,'maj'],[5,'min'],[0,'min'],[7,'dom7'],[0,'min']],
 'minor|eerie':[[0,'min'],[5,'min'],[0,'min'],[7,'dom7'],[8,'maj'],[5,'min'],[7,'dom7'],[0,'min']],
 'lydian|dreamy':[[0,'maj7'],[2,'maj'],[0,'maj7'],[7,'maj'],[2,'maj'],[0,'maj7'],[7,'dom7'],[0,'maj7']],
};
const _RA_RHY={
 bright:[[0.5,0.5,1,1,1],[1,0.5,0.5,1,1],[0.5,0.5,0.5,0.5,1,1],[0.5,0.5,1,0.5,0.5,1]],
 driving:[[0.5,0.5,1,1,1],[1,0.5,0.5,1,1],[0.5,0.5,0.5,0.5,1,1],[1,1,0.5,0.5,1]],
 grand:[[2,1,1],[1.5,0.5,2],[1,1,1,1],[2,2]],
 gentle:[[1.5,0.5,2],[2,2],[1,1,2],[1.5,0.5,1,1]],
 sad:[[1.5,0.5,2],[2,2],[1,1,2],[2,1,1]],
 dreamy:[[1,1,1,1],[2,1,1],[1,0.5,0.5,2],[1.5,0.5,2]],
 eerie:[[2,2],[1,1,2],[2,1,1],[1.5,0.5,2]],
 aggressive:[[0.5,0.5,0.5,0.5,1,1],[0.5,0.5,1,0.5,0.5,1],[1,0.5,0.5,0.5,0.5,1],[0.5,0.5,0.5,0.5,0.5,0.5,1]],
};
const _RA_BASS={bright:'walk',driving:'walk',grand:'grand',gentle:'sus',sad:'sus',dreamy:'arp',eerie:'spar',aggressive:'ost'};
const _RA_COMP={bright:'off',driving:'off',grand:'rich',gentle:'arp',sad:'arp',dreamy:'arp',eerie:'spar',aggressive:'pow'};
const _RA_CENTER={bright:76,driving:74,grand:72,gentle:72,sad:69,dreamy:76,eerie:69,aggressive:76};
const _RA_LIFT=[0,2,3,5,9,6,3,0];
function _RA_mul(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function _RA_hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function _RA_arrange(rootPc, mode, character, tempo, seedStr){
  const rng=_RA_mul(_RA_hash(seedStr||(mode+character)));
  const pick=arr=>arr[Math.floor(rng()*arr.length)];
  const prog=_RA_PROG[mode+'|'+character]||_RA_PROG[mode+'|gentle']||_RA_PROG['major|gentle'];
  const scale=_RA_SCALE[mode]||_RA_SCALE.major;
  const scaleSet=new Set(scale.map(x=>(x+rootPc)%12));
  const bars=prog.map(([off,type])=>({rootPc:(rootPc+off)%12,type,tones:_RA_CHORD[type].map(iv=>(rootPc+off+iv)%12)}));
  const notes=[];
  const add=(m,b,d)=>notes.push({note:noteName(m),dur:d,beat:+b.toFixed(3)});
  const bassMidi=pc=>{let m=36+pc;if(m>43)m-=12;return m;};
  const voic=(pc,type)=>{let base=48+pc;if(base>59)base-=12;return _RA_CHORD[type].map(iv=>base+iv);};
  // BASS
  const bs=_RA_BASS[character];
  for(let i=0;i<8;i++){const base=i*4;const R=bassMidi(bars[i].rootPc);const NR=bassMidi(bars[(i+1)%8].rootPc);
    if(bs==='walk'){add(R,base,1);add(R+7,base+1,1);add(R,base+2,1);add(NR-1,base+3,1);}
    else if(bs==='ost'){for(let k=0;k<8;k++)add(R,base+k*0.5,0.5);}
    else if(bs==='grand'){add(R,base,2);add(R+12,base+2,2);}
    else if(bs==='arp'){add(R,base,1.5);add(R+7,base+1.5,1.5);add(R+12,base+3,1);}
    else if(bs==='spar'){add(R,base,4);}
    else {add(R,base,4);add(R+12,base+2,2);}
  }
  // COMP
  const cs=_RA_COMP[character];
  for(let i=0;i<8;i++){const base=i*4;const V=voic(bars[i].rootPc,bars[i].type);
    if(cs==='off'){for(const n of V)add(n,base,0.25);for(const off of[0.5,1.5,2.5,3.5])for(const n of V)add(n,base+off,0.25);}
    else if(cs==='pow'){const pw=[V[0],V[0]+7];add(pw[0],base,0.25);for(const off of[0.5,1.5,2.5,3.5])for(const n of pw)add(n,base+off,0.25);}
    else if(cs==='rich'){for(const n of V)add(n,base,4);}
    else if(cs==='spar'){add(V[0],base,4);if(V[1])add(V[1],base+2,2);}
    else {add(V[0],base,1.5);if(V[1])add(V[1],base+1.5,1.5);if(V[2])add(V[2],base+3,1);}
  }
  // MELODY (motif → arc to bar4 climax → cadence)
  const center=_RA_CENTER[character]||72; const ceil=center+13, floor=center-11;
  const inScale=m=>scaleSet.has(((m%12)+12)%12);
  const cands=(tp)=>{const a=[];for(let m=floor;m<=ceil;m++)if(tp.has(((m%12)+12)%12))a.push(m);return a;};
  const pickTone=(cur,tp,target,avoid)=>{const a=cands(tp);if(!a.length)return cur;a.sort((x,y)=>(Math.abs(x-target)+0.6*Math.abs(x-cur)+rng()*0.4)-(Math.abs(y-target)+0.6*Math.abs(y-cur)+rng()*0.4));for(const m of a){if(m!==avoid)return m;}return a[0];};
  const stepScale=(cur,dir)=>{let m=cur+dir;for(let k=0;k<3;k++){if(inScale(m))return m;m+=dir;}return cur+dir;};
  let prev=center; const rhy=_RA_RHY[character]||_RA_RHY.gentle; const cell0=pick(rhy);
  for(let i=0;i<8;i++){const base=i*4;const tp=new Set(bars[i].tones);const target=center+_RA_LIFT[i];
    const cell=(i===0||i===2)?cell0:(i===7?[2,1,1]:pick(rhy)); let b=base;
    for(let j=0;j<cell.length;j++){const d=cell[j];const rel=+(b-base).toFixed(3);const strong=(rel%2===0);
      let pitch;
      if(i===7&&j===cell.length-1){pitch=pickTone(prev,new Set(bars[7].tones),center,null);}
      else if(strong){pitch=pickTone(prev,tp,target,prev);}
      else{let dir=Math.sign(target-prev)||(rng()<0.5?1:-1);if(rng()<0.22)dir=-dir;pitch=stepScale(prev,dir);if(pitch===prev)pitch=stepScale(prev,dir);if(!inScale(pitch))pitch=pickTone(prev,tp,target,prev);}
      pitch=Math.max(floor-2,Math.min(ceil,pitch)); add(pitch,b,d); prev=pitch; b+=d;
    }
  }
  return {tempo,notes};
}

// Generate a piece (~32 beats) from a free-text mood. Returns a song object
// shaped like SONG_LIBRARY entries: {mood,title,tempo,notes:[{note,dur,beat}]}.
// Uses the rich arranger above, with mode+character inferred from the mood's
// valence/energy profile — so any typed mood gets a full-bodied composition.
function moodToSong(text){
  const label=(text||'').trim(); if(!label) return null;
  const P=_moodParams(label.toLowerCase());
  const v=P.v, e=P.e;
  const mode = (v>=0.5 && e>0.7) ? 'lydian' : (v>=0 ? 'major' : 'minor');
  let ch;
  if(mode==='lydian') ch='dreamy';
  else if(v<=-0.2 && e<0.4) ch='eerie';
  else if(e>=0.7 && v<0) ch='aggressive';
  else if(e>=0.7 && v>=0.4) ch='bright';
  else if(e>=0.7) ch='driving';
  else if(e>=0.5 && v>=0.6) ch='grand';
  else if(e>=0.5 && v>=0.25) ch='bright';
  else if(e>=0.45 && v<0) ch='driving';
  else if(e<0.4 && v<-0.05) ch='sad';
  else ch = v<0 ? 'sad' : 'gentle';
  const out=_RA_arrange(P.root, mode, ch, P.tempo, label.toLowerCase());
  return { mood:label, title:label.charAt(0).toUpperCase()+label.slice(1), tempo:out.tempo, notes:out.notes };
}

// Atmosphere transform: re-colour an image's literal colour→notes piece with a
// detected mood (valence v / energy e). Snaps pitches to the mood scale (harmony),
// scales velocity (dynamics) and time (tempo). Returns NEW events; pass the literal
// events each time so toggling off restores the original.
function _atmoTransform(evts, mood, skipTiming){
  if(!evts||!evts.length||!mood) return evts;
  const v=Math.max(-1,Math.min(1,mood.v||0)), e=Math.max(0,Math.min(1,mood.e==null?0.5:mood.e));
  const sm=(v>=0.5&&e>0.7)?'lydian':(v>=0?'major':'minor');
  const SC=({major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10],lydian:[0,2,4,6,7,9,11]})[sm];
  const root=((mood.root||0)%12+12)%12;
  const tempoK=1.35-e*0.8;     // calm → slower, intense → faster
  const vScale=0.6+e*0.6;      // calm → softer, intense → louder
  const snap=(m)=>{ const pc=((m-root)%12+12)%12; let best=SC[0],bd=99; for(const d of SC){ const dd=Math.min(((pc-d)%12+12)%12,((d-pc)%12+12)%12); if(dd<bd){bd=dd;best=d;} } let delta=((best-pc)%12+12)%12; if(delta>6) delta-=12; return m+delta; };
  // skipTiming: for IMAGE mode, pixelsToImageEvents already shaped tempo, rhythm,
  // density and dynamics from the (atmo-blended) energy — so here we ONLY do the
  // harmonic snap to the mood's scale, leaving timing & velocity untouched to
  // avoid double-scaling the tempo/loudness.
  if(skipTiming){
    return evts.map(ev=>({ ...ev, n:(ev.n||[]).map(no=>({ ...no, m:snap(no.m) })) }));
  }
  return evts.map(ev=>({ ...ev, startMs:Math.round((ev.startMs||0)*tempoK), n:(ev.n||[]).map(no=>({ ...no, m:snap(no.m), v:Math.max(20,Math.min(124,Math.round((no.v||80)*vScale))), durMs:Math.max(40,Math.round((no.durMs||300)*tempoK)) })) }));
}

// ─── MELODY layer ────────────────────────────────────────────────────────────
// "obraz spieva": lay an AI-composed SINGING melodic line ON TOP of the scan
// texture. The scan piece stays exactly as-is (the literal colours→notes of the
// image) — this only ADDS a lead voice that mirrors the image's mood, colour and
// radiance. The result is the SAME scan composition, beautified and singable —
// not a different piece (that's what aiComposeFromImage does instead).
//
// `evts`     — the scan events {n:[{m,v,durMs}],startMs,...} (already atmo-snapped
//              if atmosphere is on). NEVER mutated — we return a fresh copy.
// `mel`      — { notes:[[pitch,durBeats,startBeat,velocity],...], tempo } from AI,
//              where pitch is a name like "C5"/"F#4" (name2midi-parseable) OR a
//              MIDI number.
//
// How it stays a LEAD voice over the texture:
//   • Time-scaled to the scan piece's full span, so the melody breathes across
//     the whole painting rather than racing ahead or lagging.
//   • Lifted in register to sit ABOVE the texture's top note (octave-shifted up
//     until it clears the scan ceiling) — the ear reads it as the melody.
//   • Prominent velocity (lead voice), longer notes kept long (lyrical).
//   • Each melody note is time-merged into the nearest scan event (so the scan
//     step-loop, which reads chordsRef live, plays texture + melody together —
//     no second scheduler). Tagged _lead so playback can treat it specially.
// MELODY as a SEPARATE VOICE. Instead of splicing melody notes into the texture
// events (which forces them through the single-track step-loop and chops them into
// disjointed ticks), this returns the texture UNCHANGED plus a standalone `voice`:
// a list of melody notes keyed by PROPORTIONAL position in the piece (pos 0..1).
// The player schedules that voice on its own timers, in parallel with the texture,
// so the sung line flows continuously over the (dynamically-paced) texture — two
// real voices at once. Position is proportional (not absolute ms) so it lands
// correctly however the texture's dynamic tempo stretches the timeline.
//
// Returns { events, voice } — events is the texture (clone, never mutated); voice
// is [{pos, m, v, durMs}] or [] if nothing to sing.
// ── MELODY FITTED TO THE TEXTURE ─────────────────────────────────────────────
// The AI writes its line from the picture alone, in its own key and tempo. Laid
// over a composer (Satie's slow chords, Bach's running notes) or a scan as-is it
// clashed: wrong key, its own fast pulse, high and loud — a hail of notes. Here
// the line keeps only its CONTOUR and RHYTHMIC PROPORTIONS and is re-set onto the
// texture that actually plays:
//   • key   — the texture's own key (Krumhansl), every note on that scale
//   • harmony — a note that would rub (semitone / tritone) against what sounds at
//               that moment moves to the nearest tone of that chord
//   • pulse — notes land ON the texture's onsets (never faster than ~2.5 / s,
//             one per chord when the texture is slow), long notes span several
//   • voice — just above the texture, never above C6, a touch louder than it,
//             legato; the AI's own chords are dropped (the texture is the harmony)
//   • form  — texture-only intro, the phrase, a breath, the answer (an octave up
//             when it fits), … and a texture-only close
// evT = the time (ms) each texture event starts in real playback; totalMs = the
// whole length. Returns { events, voice } like _melodyVoice, or null.
function _melodyFit(evts, mel, atmo, evT, totalMs){
  const n=evts.length; if(n<2) return null;
  // ── the line: contour + rhythm of the AI cell
  const raw=[];
  for(const r of mel.notes){
    if(!Array.isArray(r)||r.length<3) continue;
    let m=r[0]; if(typeof m==='string') m=name2midi(m);
    if(typeof m!=='number'||!isFinite(m)) continue;
    raw.push({ m, b:Math.max(0,+r[2]||0), d:Math.max(0.25,+r[1]||0.5), v:Math.max(1,Math.min(127,Math.round(+r[3]||90))) });
  }
  if(raw.length<2) return null;
  raw.sort((a,b)=>a.b-b.b);
  const cell=[]; for(const x of raw){ const l=cell[cell.length-1]; if(l && Math.abs(l.b-x.b)<1e-6){ if(x.m>l.m) cell[cell.length-1]=x; } else cell.push(x); }   // one line: top note of any stacked onset
  if(cell.length<2) return null;
  const iois=[]; for(let i=0;i<cell.length-1;i++) iois.push(cell[i+1].b-cell[i].b);
  const _cnt=new Map(); for(const d of iois){ const q=Math.max(0.125,Math.round(d*8)/8); _cnt.set(q,(_cnt.get(q)||0)+1); }
  let unit=0.5, _best=-1; for(const [q,c] of _cnt){ if(c>_best || (c===_best && q<unit)){ _best=c; unit=q; } }
  const lens=cell.map((x,i)=> Math.max(1, Math.min(4, Math.round((i<iois.length ? iois[i] : x.d)/unit))));
  const phraseSlots=lens.reduce((a,b)=>a+b,0);
  // ── the texture: onsets grouped, what sounds when, its key, loudness, register
  const evNotes=evts.map(e=>(e&&e.n)||[]);
  const groups=[]; for(let k=0;k<n;k++){ const t=evT[k]|0; const g=groups[groups.length-1]; if(g && t-g.t<35) g.ks.push(k); else groups.push({t, ks:[k]}); }
  const pcH=new Array(12).fill(0), vels=[], tops=[];
  for(let k=0;k<n;k++){ let top=0; for(const no of evNotes[k]){ const w=(no.v||64)*Math.min(4,Math.max(.25,(no.durMs||300)/400)); pcH[((no.m%12)+12)%12]+=w; vels.push(no.v||64); if(no.m>top) top=no.m; } if(top) tops.push(top); }
  if(!vels.length) return null;
  const MAJ=[6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88], MIN=[6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17];
  const corr=(prof,root)=>{ let mx=0,my=0; for(let i=0;i<12;i++){ mx+=pcH[(i+root)%12]; my+=prof[i]; } mx/=12; my/=12; let a=0,bx=0,by=0; for(let i=0;i<12;i++){ const dx=pcH[(i+root)%12]-mx, dy=prof[i]-my; a+=dx*dy; bx+=dx*dx; by+=dy*dy; } return (bx>0&&by>0)?a/Math.sqrt(bx*by):-1; };
  let root=0, minor=false, kb=-2; for(let r=0;r<12;r++){ const a=corr(MAJ,r), b=corr(MIN,r); if(a>kb){kb=a;root=r;minor=false;} if(b>kb){kb=b;root=r;minor=true;} }
  const scale=(minor?[0,2,3,5,7,8,10]:[0,2,4,5,7,9,11]).map(d=>(d+root)%12);
  vels.sort((a,b)=>a-b); tops.sort((a,b)=>a-b);
  const texVel=vels[Math.floor(vels.length*0.6)];
  const texTop=tops.length ? tops[Math.floor(tops.length*0.75)] : 72;
  const soundingAt=(T)=>{ const pcs=new Set(); for(let k=0;k<n;k++){ const t=evT[k]; if(t>T+35) break; if(t<T-6000) continue; for(const no of evNotes[k]){ if(t+(no.durMs||300)>=T-10) pcs.add(((no.m%12)+12)%12); } } return pcs; };
  // ── slots: the texture's onsets, thinned to a singable pulse (≥ ~400 ms apart);
  // a long chord is divided (~600 ms steps) so over a slow texture the line can
  // still move — those in-between notes sit on the chord that is still sounding
  const MIN_STEP=400, slots=[];
  const fill=(a,b)=>{ const parts=Math.max(1, Math.min(4, Math.round((b-a)/600))); for(let q=1;q<parts;q++) slots.push(Math.round(a+(b-a)*q/parts)); };
  for(let i=0;i<groups.length;i++){
    const t=groups[i].t, last=slots[slots.length-1];
    if(last!=null && t-last<MIN_STEP*0.9) continue;
    if(last!=null) fill(last, t);
    slots.push(t);
  }
  { const end=totalMs-200, last=slots[slots.length-1]; if(last!=null) fill(last, end); }
  if(slots.length<8) return { events:evts, voice:[] };   // too short to sing over: no line rather than the free-tempo hail
  // ── register: whole-octave shift so the line sits just over the texture, within E3..C6
  let lo=128, hi=0; for(const x of cell){ if(x.m<lo) lo=x.m; if(x.m>hi) hi=x.m; }
  const LO=52, HI=84, floor=Math.min(HI-(hi-lo), texTop+3);
  const cands=[-36,-24,-12,0,12,24,36].filter(L=>lo+L>=LO && hi+L<=HI);
  let lift = cands.length ? cands.reduce((best,L)=>{ const ok=(lo+L)>=floor, bok=(lo+best)>=floor; if(ok&&!bok) return L; if(ok&&bok) return L<best?L:best; if(!ok&&!bok) return L>best?L:best; return best; }, cands[0])
                          : Math.round((72-(lo+hi)/2)/12)*12;
  // ── pitch: on the scale, and no semitone / tritone against what sounds
  const onScale=(m)=>{ for(let d=0;d<=2;d++){ for(const s of (d? [m-d,m+d] : [m])){ if(scale.includes(((s%12)+12)%12)) return s; } } return m; };
  const fitPitch=(m,T)=>{
    let p=onScale(m);
    const pcs=soundingAt(T); if(!pcs.size) return p;
    const rub=(x)=>{ const pc=((x%12)+12)%12; for(const t of pcs){ const ic=Math.min(((pc-t)%12+12)%12, ((t-pc)%12+12)%12); if(ic===1||ic===6) return true; } return false; };
    if(!rub(p)) return p;
    let best=null, bd=99;
    for(let d=1; d<=4; d++){ for(const c of [p-d,p+d]){ const pc=((c%12)+12)%12; if(pcs.has(pc) && !rub(c)){ const sc=d+(scale.includes(pc)?0:0.5); if(sc<bd){bd=sc;best=c;} } } if(best!=null) break; }
    if(best==null){ for(let d=1; d<=3 && best==null; d++){ for(const c of [p-d,p+d]){ if(scale.includes(((c%12)+12)%12) && !rub(c)){ best=c; break; } } } }
    return best!=null ? best : p;
  };
  // ── form: intro, phrase, breath, answer … close
  const introS=Math.max(2, Math.min(Math.round(slots.length*0.1), slots.findIndex(t=>t>=8000)>0 ? slots.findIndex(t=>t>=8000) : 6));
  const outroS=Math.max(2, Math.round(slots.length*0.08));
  const restS=Math.max(2, Math.round(phraseSlots*0.5));
  const _atmoE=(atmo && typeof atmo.e==='number') ? atmo.e : null;
  const velShift=(_atmoE!=null) ? (_atmoE<0.5 ? -8*(0.5-_atmoE)/0.5 : 6*(_atmoE-0.5)/0.5) : 0;
  const placed=[];
  let s0=introS, E=0;
  while(s0+Math.min(phraseSlots,4) < slots.length-outroS){
    const oct=(E%2===1 && hi+lift+12<=HI) ? 12 : 0;
    let si=s0; const startCount=placed.length;
    for(let i=0;i<cell.length;i++){
      if(si>=slots.length-outroS) break;
      const T=slots[si], L=lens[i];
      const endI=Math.min(slots.length-1, si+L);
      const endT=(endI>si) ? slots[endI] : T+600;
      placed.push({ T, end:endT, m:cell[i].m+lift+oct, v0:cell[i].v, i });
      si+=L;
    }
    if(placed.length===startCount) break;
    s0=si+restS; E++;
  }
  if(!placed.length) return null;
  const voice=[];
  const nP=placed.length;
  for(let j=0;j<nP;j++){
    const p=placed[j];
    const m=Math.max(LO, Math.min(HI+2, fitPitch(p.m, p.T)));
    const arcPos=p.T/totalMs, climax=1-Math.abs(arcPos-0.72)*1.2, dyn=0.88+0.12*Math.max(0,Math.min(1,climax));
    const edge=1-Math.abs((p.i/Math.max(1,cell.length-1))-0.5)*0.4;
    const v=Math.max(Math.min(60,texVel+6), Math.min(100, Math.round((texVel*1.2+10+velShift)*dyn*edge + (p.v0-90)*0.08)));
    const durMs=Math.max(260, Math.min(3200, (p.end-p.T)*1.05));
    voice.push({ pos:Math.min(1,p.T/totalMs), durFrac:durMs/totalMs, m, v });
  }
  voice.sort((a,b)=>a.pos-b.pos);
  return { events:evts, voice, key:{root, minor} };
}

function _melodyVoice(evts, mel, atmo, totalMs, evT){
  const empty={ events:evts, voice:[] };
  if(!evts||!evts.length||!mel||!mel.notes||!mel.notes.length) return empty;
  // With the texture's real timeline the line is FITTED to what plays under it
  // (key, chords, pulse, loudness) — see _melodyFit. The free-tempo loop below is
  // the fallback when no timeline is given.
  if(Array.isArray(evT) && evT.length===evts.length && typeof totalMs==='number' && totalMs>0){
    try{ const f=_melodyFit(evts, mel, atmo, evT, totalMs); if(f) return f; }catch(_){}
  }
  // KEY MATCH: when ATM is on, the texture has been snapped to a mood scale
  // (root + major/minor/lydian). Snap the melody + chords to the SAME scale so the
  // sung line stays in tune with the retuned texture instead of clashing.
  let snap=(m)=>m;
  if(atmo && typeof atmo.v==='number' && typeof atmo.e==='number'){
    const v=atmo.v, e=atmo.e;
    const sm=(v>=0.5&&e>0.7)?'lydian':(v>=0?'major':'minor');
    const SC=({major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10],lydian:[0,2,4,6,7,9,11]})[sm];
    // ATMO root was historically hardcoded to 0 (always C) — a bug. If no usable
    // root supplied, derive it from the scan texture's pitch-class histogram so the
    // melody snaps to the same tonic the scan already chose (Krumhansl key detection).
    let root;
    if(typeof atmo.root==='number' && atmo.root>0){
      root=((atmo.root|0)%12+12)%12;
    } else {
      const pcH=new Array(12).fill(0);
      for(const ev of evts) for(const no of (ev.n||[])) pcH[((no.m%12)+12)%12]+=(no.v||64);
      let bestPc=0,bestW=-1; for(let i=0;i<12;i++) if(pcH[i]>bestW){bestW=pcH[i];bestPc=i;}
      root=bestPc;
    }
    snap=(m)=>{ const pc=((m-root)%12+12)%12; let best=SC[0],bd=99; for(const d of SC){ const dd=Math.min(((pc-d)%12+12)%12,((d-pc)%12+12)%12); if(dd<bd){bd=dd;best=d;} } let delta=((best-pc)%12+12)%12; if(delta>6) delta-=12; return m+delta; };
  }
  // Texture ceiling so the melody can sit just above it: the 90th percentile of
  // each event's top note, not the single highest pitch — a few octave-doubled
  // peaks (a composer's agitato, a bright scan cell) must not decide the register.
  const _tops=[];
  for(const ev of evts){ let top=0; for(const no of (ev.n||[])){ if(no.m>top) top=no.m; } if(top>0) _tops.push(top); }
  _tops.sort((a,b)=>a-b);
  const scanHi=_tops.length ? _tops[Math.min(_tops.length-1, Math.floor(_tops.length*0.9))] : 72;
  // Parse melody notes into {m, startBeat, durBeats, vel}.
  const parsed=[];
  let melMinBeat=Infinity, melMaxBeat=-Infinity, melHi=0, melLo=128;
  for(const raw of mel.notes){
    if(!Array.isArray(raw)||raw.length<3) continue;
    let m=raw[0];
    if(typeof m==='string') m=name2midi(m);
    if(typeof m!=='number'||!isFinite(m)) continue;
    m=snap(m);
    const durB=Math.max(0.25, +raw[1]||0.5);
    const startB=Math.max(0, +raw[2]||0);
    const vel=Math.max(1,Math.min(127, Math.round(+raw[3]||100)));
    parsed.push({m, startB, durB, vel});
    if(startB<melMinBeat)melMinBeat=startB;
    if(startB+durB>melMaxBeat)melMaxBeat=startB+durB;
    if(m>melHi)melHi=m; if(m<melLo)melLo=m;
  }
  if(!parsed.length||!isFinite(melMinBeat)||melMaxBeat<=melMinBeat) return empty;
  // Register lift: shift the melody up by whole octaves so it sits just above the
  // texture top — sings as a layer over it, stays singable.
  // Register lift target: serene atmo wants the line low and intimate (just over
  // the texture); agitato wants it soaring above. Floor offset shifts by -2..+4.
  const _atmoE = (atmo && typeof atmo.e==='number') ? atmo.e : null;
  const _liftFloorShift = (_atmoE!=null)
    ? (_atmoE<0.5 ? -2*(0.5-_atmoE)/0.5 : +4*(_atmoE-0.5)/0.5)
    : 0;
  // The line must stay singable: never above A6 (93), never below E3 (52). Pick the
  // octave shift that keeps the WHOLE line in that range and sits it above the
  // texture; when the texture is too high for that, the line keeps its best
  // register inside it. (The old loop could lift past the top, and the per-note
  // clamp then squashed the whole tune onto one repeated C#7.)
  const targetFloor=scanHi+4+Math.round(_liftFloorShift);
  // Only ever lift — a line the AI wrote too high is the one case that comes down.
  const _cands=[-24,-12,0,12,24,36].filter(L=> melHi+L<=93 && melLo+L>=52);
  const _up=_cands.filter(L=>L>=0);
  let lift=null;
  if(_up.length){ for(const L of _up){ if(melLo+L>=targetFloor){ lift=L; break; } lift=L; } }
  else if(_cands.length){ lift=Math.max(..._cands); }
  if(lift===null) lift=Math.round((79-(melLo+melHi)/2)/12)*12;   // a line wider than the range: centre it on G5
  // Lead velocity — default 92..120. Mood reshapes it: serene softens (down to
  // ~78..104), agitato hardens (up to ~102..127), so the melody actually sings
  // quieter on a calm tag and louder on a frantic one.
  const _velShift = (_atmoE!=null)
    ? (_atmoE<0.5 ? -14*(0.5-_atmoE)/0.5 : +7*(_atmoE-0.5)/0.5)
    : 0;
  const leadVel=(v)=> Math.max(40, Math.min(127, Math.round(90 + (v/127)*30 + _velShift)));

  // ── LOOP MODEL ─────────────────────────────────────────────────────────────
  // The AI writes ONE short, continuous melodic cell (a real phrase, dense and
  // singable). We do NOT stretch those few notes across the whole 2–3 min scan
  // (that turns a melody into one isolated note every couple of seconds). Instead
  // we measure the cell's real length in SECONDS (beats ÷ tempo) and REPEAT it
  // back-to-back for the whole painting, so the listener always hears a continuous
  // tune, looping like a song over the texture — not sparse drips.
  const tempo = (mel.tempo && mel.tempo>20 && mel.tempo<260) ? mel.tempo : 90;
  const secPerBeat = 60/tempo;
  const cellBeats = melMaxBeat - melMinBeat;            // length of one melodic cell, in beats
  const cellSec = Math.max(2, cellBeats*secPerBeat);    // …in seconds
  // Total texture duration in seconds: the REAL playback length measured by the
  // player (totalMs) when given — so the line keeps the AI's tempo over a scan or a
  // composer piece alike — else estimated from the last texture event's timing.
  const lastEv = evts[evts.length-1];
  const scanSec = (typeof totalMs==='number' && totalMs>0)
    ? Math.max(cellSec, totalMs/1000)
    : Math.max(cellSec, ((lastEv && (lastEv.startMs||0)) || (evts.length*150)) / 1000 + 0.5);

  // Build one cell as {tBeat (from 0), durB, m, v} for melody, plus chords.
  const cellNotes = parsed.map(p=>({ tBeat:p.startB-melMinBeat, durB:p.durB, m:Math.max(40,Math.min(100,p.m+lift)), v:leadVel(p.vel) }))
                          .sort((a,b)=>a.tBeat-b.tBeat);
  const cellChords=[];
  if(Array.isArray(mel.chords) && mel.chords.length){
    for(const raw of mel.chords){
      if(!Array.isArray(raw)||raw.length<3) continue;
      const pitches=raw[0]; if(!Array.isArray(pitches)||!pitches.length) continue;
      const durB=Math.max(0.25, +raw[1]||1);
      const startB=Math.max(0, +raw[2]||0);
      const vel=Math.max(1,Math.min(127, Math.round(+raw[3]||80)));
      const ms=[];
      for(const p of pitches){ let m=typeof p==='string'?name2midi(p):p; if(typeof m==='number'&&isFinite(m)){ ms.push(Math.max(33,Math.min(88,snap(m)))); } }
      if(ms.length) cellChords.push({ tBeat:Math.max(0,startB-melMinBeat), durB, ms, v:Math.max(58,Math.min(96,Math.round(vel*0.82))) });
    }
  }

  // ── FORM ───────────────────────────────────────────────────────────────────
  // A real piece breathes: it does NOT loop the same tune nonstop for 2½ minutes.
  // The texture establishes alone, the melody ENTERS, sings its phrase, then steps
  // back to let the painting breathe, returns, lifts to a climax, and bows out —
  // leaving the texture to close. So instead of filling 0..1 with back-to-back
  // loops, we place a FEW melody entries at musically sensible windows, with
  // texture-only gaps between them.
  //
  // The cell occupies cellFrac of the whole timeline. We choose entry points (as
  // fractions 0..1) scaled to how many cells fit, so a short scan gets 1–2 entries
  // and a long one gets 4–5 — never wall-to-wall.
  // ATMO cell stretch: serene atmo widens the melodic cell across more of the
  // timeline so the notes spread out in real time (slow scan + dense melody used
  // to feel like the song sped up when melody came on). Frantic slightly shrinks.
  // Serene atmoE=0 → ×2.5; neutral → ×1.0; frantic atmoE=1 → ×0.85.
  const _cellStretch = (_atmoE!=null)
    ? (_atmoE<0.5 ? +1.5*(0.5-_atmoE)/0.5 : -0.15*(_atmoE-0.5)/0.5)
    : 0;
  // No floor that would stretch the line on a long piece: the cell keeps the AI's
  // tempo (times the atmo stretch) whatever the painting's length.
  const cellFrac = Math.min(0.7, Math.max(0.005, (cellSec/scanSec) * (1 + _cellStretch)));
  // Texture-only intro and outro: ~14 % / 12 % of the piece, but never more than
  // ~8 s — on a five-minute piece the line must not wait 40 s to come in.
  const _intro = Math.min(0.14, 8/scanSec), _outro = Math.min(0.12, 8/scanSec);
  // How many entries the piece can host (leave room for intro + gaps + outro).
  const capacity = Math.floor((1 - _intro - _outro) / (cellFrac*1.7 /*gap≈0.7·cell*/));
  // Serene atmo prefers fewer entries (more breath, fewer reps); agitato fills in.
  const _entryBias = (_atmoE!=null) ? (_atmoE<0.5 ? -1 : (_atmoE>0.7 ? +1 : 0)) : 0;
  const entries = Math.max(1, Math.min(8, capacity + _entryBias));
  // Distribute entry start-positions: first after the texture-only intro, spread
  // evenly, last finishing before the texture-only outro.
  const firstStart = _intro;
  const lastStart  = Math.max(firstStart, 1 - _outro - cellFrac);
  const span = (entries>1) ? (lastStart-firstStart)/(entries-1) : 0;

  const voice=[];
  const beatToFrac = cellBeats>0 ? (cellFrac/cellBeats) : 0;   // beats → fraction of timeline
  const cellHi = cellNotes.reduce((a,n)=>Math.max(a,n.m),0);   // cell's own peak (for phrase-arc shaping)
  for(let E=0;E<entries;E++){
    const base = (entries>1) ? (firstStart + E*span) : firstStart;
    // Dynamic shape across the whole piece: gentle first entry, fullest near the
    // climax (~78% through), settling at the very end.
    const arc = entries>1 ? E/(entries-1) : 0.6;
    const climax = 1 - Math.abs(arc-0.78)*1.4;
    const dynMul = 0.82 + 0.18*Math.max(0,Math.min(1,climax));
    // #5 VARIATION ON RETURN: the first statement is the plain theme. Each return
    // is varied so the piece develops instead of repeating — alternate returns lift
    // an octave (when it stays in range), and later returns sing a touch brighter.
    // Entry 0 = theme; entry 1 = octave-up answer; entry 2 = theme (climax, full);
    // entry 3 = octave-up; … This is what keeps repeats from getting tiresome.
    // Strong-calm atmo: no octave-up answer (no large leaps in a dream).
    let octShift = 0;
    const _noLeap = (_atmoE!=null && _atmoE<0.30);
    if(!_noLeap && E>0 && (E%2===1) && cellHi+12 <= 93) octShift = 12;
    // #3 INTRA-PHRASE DYNAMICS: within each entry, swell toward the melodic peak
    // and ease off at the phrase ends, so the line breathes like a singer rather
    // than playing every note at one level.
    for(let i=0;i<cellNotes.length;i++){
      const cur=cellNotes[i], nxt=cellNotes[i+1];
      const pos=base + cur.tBeat*beatToFrac;
      if(pos>=1) continue;
      // phrase-arc factor: higher notes / mid-phrase louder, edges softer.
      const pitchRise = cellHi>0 ? (cur.m/cellHi) : 1;                  // ~0.8..1 across the cell's range
      const edge = 1 - Math.abs((i/(Math.max(1,cellNotes.length-1)))-0.5)*0.5; // mid-phrase fuller
      const shape = 0.84 + 0.16*Math.max(0,Math.min(1,(pitchRise-0.8)/0.2))*edge;
      let durFrac;
      if(nxt){ durFrac=Math.max(0.004,(nxt.tBeat-cur.tBeat)*beatToFrac*1.08); }
      else   { durFrac=Math.max(0.004, cur.durB*beatToFrac*1.0); }
      // #1 PEDAL: let melody notes ring a little past the next onset (sustain-pedal
      // bleed) so the line is connected and resonant, not dry and detached.
      durFrac=Math.min(cellFrac*1.05, durFrac);
      const m = cur.m + octShift;
      voice.push({ pos:Math.min(1,pos), durFrac, m:Math.min(100,m), v:Math.max(66,Math.min(124,Math.round(cur.v*dynMul*shape))) });
    }
    // chords under it — thin on the gentle first entry, full at climax. With PEDAL
    // the chords sustain longer for harmonic resonance under the melody.
    const withChords = (arc>0.15);
    if(withChords){
      for(const ch of cellChords){
        const pos=base + ch.tBeat*beatToFrac;
        if(pos>=1) continue;
        // pedal: hold the harmony through ~1.6× its written length for resonance,
        // capped so it doesn't smear across the next chord change.
        const durFrac=Math.min(cellFrac*1.1, Math.max(0.01, ch.durB*beatToFrac*1.6));
        for(const m of ch.ms){ voice.push({ pos:Math.min(1,pos), durFrac, m, v:Math.max(52,Math.min(98,Math.round(ch.v*dynMul))) }); }
      }
    }
  }
  voice.sort((a,b)=>a.pos-b.pos);
  return { events:evts, voice };
}

// Crossfade-morph two mood pieces into one. First half is mood A,
// second half is mood B (time-scaled to A's length), with a velocity
// crossfade in the 40-60% zone where both pieces overlap and blend.
function morphSongs(songA, songB) {
  if (!songA || !songB) return null;
  const aNotes = songA.notes;
  const bNotes = songB.notes;
  const aMax = Math.max(...aNotes.map(n => n.beat + n.dur));
  const bMax = Math.max(...bNotes.map(n => n.beat + n.dur));
  const bScale = aMax / bMax;
  const fadeStart = aMax * 0.40;
  const fadeEnd   = aMax * 0.60;
  const merged = [];
  for (const n of aNotes) {
    if (n.beat >= fadeEnd) continue;
    let factor = 1;
    if (n.beat > fadeStart) factor = 1 - (n.beat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, _vScale: factor });
  }
  for (const n of bNotes) {
    const scaledBeat = n.beat * bScale;
    if (scaledBeat < fadeStart) continue;
    let factor = 1;
    if (scaledBeat < fadeEnd) factor = (scaledBeat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, beat: scaledBeat, _vScale: factor });
  }
  merged.sort((a, b) => a.beat - b.beat);
  return {
    notes: merged,
    tempo: Math.round((songA.tempo + songB.tempo) / 2),
    title: songA.mood + ' → ' + songB.mood
  };
}

// Chain-morph through a sequence of moods: A → B → C → D. Each consecutive pair
// crossfades like morphSongs, and the segments are laid end-to-end so the piece
// travels through every chosen mood in order. `songs` is an array of song objects
// (length 2..4: the current mood followed by 1–3 targets).
function morphChain(songs) {
  if (!songs || songs.length < 2) return null;
  const valid = songs.filter(Boolean);
  if (valid.length < 2) return null;
  // Build each A→B segment, then concatenate by offsetting each segment's beats
  // to start where the previous one ended.
  const out = [];
  let beatOffset = 0;
  let tempoSum = 0, tempoN = 0;
  const titleParts = [valid[0].mood];
  for (let i = 0; i < valid.length - 1; i++) {
    const seg = morphSongs(valid[i], valid[i + 1]);
    if (!seg) continue;
    const segMax = Math.max(...seg.notes.map(n => n.beat + n.dur), 0);
    for (const n of seg.notes) out.push({ ...n, beat: n.beat + beatOffset });
    beatOffset += segMax;
    tempoSum += seg.tempo; tempoN++;
    titleParts.push(valid[i + 1].mood);
  }
  if (!out.length) return null;
  return {
    notes: out,
    tempo: Math.round(tempoSum / Math.max(1, tempoN)),
    title: titleParts.join(' → ')
  };
}


// Reroll: transform a piece with random transposition, octave swaps, and
// rhythmic jitter. Preserves structure & beat positions, varies surface details.
function rerollSong(song, structureStable) {
  if (!song) return null;
  // Random transpose ±5 semitones, guaranteed nonzero
  let t;
  do { t = Math.floor(Math.random() * 11) - 5; } while (t === 0);
  const newNotes = song.notes.map(n => {
    const midi = name2midi(n.note);
    if (!midi) return n;
    let newMidi = midi + t;
    // Octave swaps + rhythmic jitter change the chord GROUPING (= structure).
    // When structureStable (Random OFF) we keep them off so only pitch — and
    // therefore only COLOR — changes; the painting's composition is preserved.
    if (!structureStable && midi > 48 && Math.random() < 0.15) {
      newMidi += Math.random() < 0.5 ? -12 : 12;
    }
    // Clamp to full piano range after all transformations
    newMidi = Math.max(21, Math.min(108, newMidi));
    const durMul = structureStable ? 1 : (0.85 + Math.random() * 0.3);
    return {
      note: noteName(newMidi),
      dur: structureStable ? n.dur : Math.max(0.25, n.dur * durMul),
      beat: n.beat
    };
  });
  return {
    notes: newNotes,
    // Tempo changes scale startMs and reshuffle chord grouping → structure.
    // Keep tempo fixed when structureStable.
    tempo: structureStable ? song.tempo : Math.max(50, song.tempo + (Math.floor(Math.random() * 21) - 10)),
    title: song.title
  };
}

// ─── Memoized keyboard keys ───────────────────────────────────────────────
// The keyboard renders 52 white + 36 black keys. Before this extraction those
// 88 divs re-rendered on every parent state change — including the 5-15Hz
// `disp` tick during playback. Now each key has primitive props plus stable
// callback refs only; React.memo skips reconciliation when nothing relevant
// for THAT key changed.
//
// pressNote / releaseNote / setHoveredKey come from useCallback/useState and
// have stable identity. pressInfo is a ref. snapped/busy/loadedMode are
// primitives. The on-mouse/on-touch handlers are recreated per render of the
// child, but that's fine — they only matter when the child actually renders,
// which memo gates.

// ─────────────────────────────────────────────────────────────────────────────
